    async def iter_transactions(self, deposit_number: str | None=None, *, start_page: int=0, size: int=100, max_pages: int=10, details: bool=False) -> AsyncIterator[JSONResponse]:
        """Yield full row objects; raise PaginationError if a page repeats or the budget is exhausted."""
