        for page in range(start_page, start_page + max_pages):
            result = await self.transactions(deposit_number, page=page, size=size, details=details)
            rows = result.get('elements')
            if not isinstance(rows, list) or any((not isinstance(row, dict) for row in rows)):
                from .errors import ProtocolError
                raise ProtocolError('Transaction history must contain an elements array of objects.')
            if not rows:
                return
            fingerprint = hashlib.sha256(json.dumps(rows, sort_keys=True).encode()).digest()
            if fingerprint in seen:
                raise PaginationError('The service repeated a transaction page.')
            seen.add(fingerprint)
            for row in rows:
                yield row
            if result.get('hasNext') is False or (result.get('hasNext') is not True and len(rows) < size):
                return
        raise PaginationError('max_pages was reached before the end of history.')

